s Gleichung "},{"type":"math","src":"\mathrm{II}","inline":true,"children":[{"text":"\mathrm{I'}"}]},{"text":" auch nach "},{"type":"math","src":"y","inline":true,"children":[{"text":"y"}]},{"text":" aufgelöst werden:"}]},{"type":"math","src":"\begin{array}{rcl}2\cdot x +3\cdot y&=&105&\vert-2 x\\\\3y&=&105-2x&\vert:3\\\\\mathrm{II'}\quad y&=&35-\dfrac{2}{3}x\end{array}","inline":false,"children":[{"text":""}]},{"type":"p","children":[{"text":"Setze nun die beiden rechten Seiten der Gleichungen "},{"type":"math","src":"\mathrm{I'}","inline":true,"children":[{"text":""}]},{"text":" und "},{"type":"math","src":"\mathrm{II'}","inline":true,"children":[{"text":""}]},{"text":" gleich:"}]},{"type":"math","src":"\begin{array}{rcl}40- x &=&35-\dfrac{2}{3}x&\vert+x\\\\40&=&35+\dfrac{1}{3}x&\vert-35\\\\5&=&\dfrac{1}{3}x&\vert\cdot3\\\\x&=&15\end{array}","inline":false,"children":[{"text":""}]},{"type":"p","children":[{"text":"Setze "},{"type":"math","src":"x=15","inline":true,"children":[{"text":"x=15"}]},{"text":" in Gleichung "},{"type":"math","src":"\mathrm{I'}","inline":true,"children":[{"text":""}]},{"text":" ein: "},{"type":"math","src":"y=40-15=25","inline":true,"children":[{"text":"y=40-15=25"}]},{"text":""}]},{"type":"p","children":[{"text":""}]},{"type":"p","children":[{"text":"Die Lösungsmenge deines Gleichungssystems lautet also :  "},{"type":"math","src":"\mathbb{L}=\{(15\vert 25)\}","inline":true,"children":[{"text":""}]},{"text":""}]},{"type":"p","children":[{"text":"","strong":true}]},{"type":"p","children":[{"text":"Antwort:","strong":true},{"text":" Das Hotel verfügt über "},{"type":"math","src":"15 ","inline":true,"children":[{"text":"15"}]},{"text":" Zweibettzimmer und über "},{"type":"math","src":"25","inline":true,"children":[{"text":"25"}]},{"text":" Dreibettzimmer."}]}],"id":"572c1afd-a1ba-4dfb-9419-271cd235c78a"},{"plugin":"text","state":[{"type":"h","level":3,"children":[{"text":"Lösung mit dem Additionsverfahren"}]},{"type":"math","src":"\begin{array}{cccccccl}
